function distanceMeters(a,b){const R=6371000,p1=a.latitude*Math.PI/180,p2=b.latitude*Math.PI/180,dp=(b.latitude-a.latitude)*Math.PI/180,dl=(b.longitude-a.longitude)*Math.PI/180;const q=Math.sin(dp/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2;return 2*R*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))}
function bearing(a,b){const p1=a.latitude*Math.PI/180,p2=b.latitude*Math.PI/180,dl=(b.longitude-a.longitude)*Math.PI/180;return Math.atan2(Math.sin(dl)*Math.cos(p2),Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dl))}
function destination(a,brng,d){const R=6371000,p1=a.latitude*Math.PI/180,l1=a.longitude*Math.PI/180,ad=d/R,p2=Math.asin(Math.sin(p1)*Math.cos(ad)+Math.cos(p1)*Math.sin(ad)*Math.cos(brng)),l2=l1+Math.atan2(Math.sin(brng)*Math.sin(ad)*Math.cos(p1),Math.cos(ad)-Math.sin(p1)*Math.sin(p2));return {latitude:p2*180/Math.PI,longitude:((l2*180/Math.PI+540)%360)-180}}
function runModel(){
 const gps=reliableGpsEvents(),kind=$("vt-scenario").value,seconds=Number($("vt-horizon").value);
 if(gps.length<2){$("vt-model-result").textContent=t().modelNeedData;return}
 const a=kind==="past"?gps[0]:gps[gps.length-2],b=kind==="past"?gps[1]:gps[gps.length-1],dt=Math.max(0.2,(b.timestamp-a.timestamp)/1000),dist=distanceMeters(a.coords,b.coords),speed=dist/dt,travel=speed*seconds,brng=bearing(a.coords,b.coords)+(kind==="past"?Math.PI:0),origin=kind==="past"?a.coords:b.coords,target=destination(origin,brng,travel),baseAccuracy=Math.max(a.accuracy||0,b.accuracy||0,5),uncertainty=Math.ceil(baseAccuracy+travel*0.2+seconds*0.35);
 const result=t().modelDetails.replace("{distance}",Math.round(travel)).replace("{uncertainty}",uncertainty);
 $("vt-model-result").textContent=(kind==="past"?t().modelPast:t().modelFuture)+" "+result;
 const source=map?.getSource("vt-scenario");if(source)source.setData({type:"FeatureCollection",features:[{type:"Feature",geometry:{type:"LineString",coordinates:[[origin.longitude,origin.latitude],[target.longitude,target.latitude]]},properties:{kind:"model"}}]});
 if(map)map.fitBounds([[origin.longitude,origin.latitude],[target.longitude,target.latitude]],{padding:80,maxZoom:18});
}
async function addAnnotation(){const description=$("vt-event-description").value.trim();if(!description){$("vt-event-feedback").textContent=t().eventMissing;return}const coords=currentPosition?{latitude:currentPosition.coords.latitude,longitude:currentPosition.coords.longitude}:null;await saveEvent("annotation",{eventType:$("vt-event-type").value,description,coords});$("vt-event-description").value="";$("vt-event-feedback").textContent=t().eventSaved}
